<script setup lang="ts">import { ref } from 'vue';import { api } from '../../api';import StrategyTabs from '../../components/common/StrategyTabs.vue';import TierCard from '../../components/common/TierCard.vue';import CitationList from '../../components/common/CitationList.vue';const strategy=ref<'school'|'major'|'city'>('major');const data=ref<any>(null);const saving=ref(false);async function generate(){data.value=await api.recommend({strategy:strategy.value,province:'河南',score:620})}async function save(){if(data.value){saving.value=true;await api.savePlan({name:'我的演示方案',strategy:strategy.value,items:data.value.tiers.flatMap((x:any)=>x.items)});saving.value=false}}</script><template><section class="content-page"><div class="eyebrow">PLAN / RECOMMEND</div><h1>我的志愿方案</h1><StrategyTabs v-model="strategy"/><div class="hero-actions"><button class="primary" @click="generate">生成演示方案 ↗</button><button v-if="data" class="text-btn" :disabled="saving" @click="save">{{saving?'保存中…':'保存方案'}}</button></div><div v-if="data" class="tier-grid"><TierCard v-for="tier in data.tiers" :key="tier.tier" :tier="tier.tier" :items="tier.items"/></div><CitationList v-if="data" :citations="data.citations"/></section></template>
